											lib.skill._snjs_shengchengpaixiaohui.fuzhi.add(card1);
											var card2 = game.createCard({ name: trigger.cards[0].name, nature: trigger.cards[0].nature, suit: trigger.cards[0].suit, number: trigger.cards[0].number });
											huode.add(card2);
